style.css:
/* Nord Theme for Stylish */

/* General Backgrounds */
body, html, div, section, article {
    background-color: #2E3440 !important; /* Dark background */
    color: #D8DEE9 !important; /* Light text color */
}

/* Headers */
h1, h2, h3, h4, h5, h6 {
    color: #81A1C1 !important; /* Frost blue for headers */
}

/* Links */
a {
    color: #88C0D0 !important; /* Arctic aqua for links */
    text-decoration: none !important;
}

a:hover {
    color: #8FBCBB !important; /* Hover effect for links */
    text-decoration: underline !important;
}

/* Inputs and Text Areas */
input, textarea, select {
    background-color: #3B4252 !important; /* Slightly lighter background */
    color: #ECEFF4 !important; /* Lighter text color */
    border: 1px solid #4C566A !important; /* Border for inputs */
}

input:focus, textarea:focus, select:focus {
    outline: none !important;
    border-color: #81A1C1 !important; /* Focus border color */
}

/* Buttons */
button {
    background-color: #5E81AC !important; /* Button background */
    color: #ECEFF4 !important; /* Button text */
    border: none !important;
    padding: 10px 15px !important;
    border-radius: 5px !important;
    cursor: pointer !important;
}

button:hover {
    background-color: #81A1C1 !important; /* Hover effect */
}

/* Tables */
table {
    border-collapse: collapse !important;
    background-color: #3B4252 !important; /* Table background */
}

th, td {
    border: 1px solid #4C566A !important; /* Table cell borders */
    padding: 10px !important;
    color: #ECEFF4 !important; /* Table text color */
}

th {
    background-color: #4C566A !important; /* Table header background */
    color: #D8DEE9 !important; /* Table header text color */
}

/* Scrollbars */
::-webkit-scrollbar {
    width: 8px !important;
}

::-webkit-scrollbar-thumb {
    background-color: #4C566A !important; /* Thumb color */
    border-radius: 5px !important;
}

::-webkit-scrollbar-thumb:hover {
    background-color: #5E81AC !important; /* Hover effect */
}

::-webkit-scrollbar-track {
    background-color: #2E3440 !important; /* Track background */
}

/* Highlights */
::selection {
    background-color: #88C0D0 !important; /* Highlight background */
    color: #2E3440 !important; /* Highlight text */
}
